def max_xor_pair(nums):
    best = 0
    mask = 0
    for bit in range(31, -1, -1):
        mask |= 1 << bit
        prefixes = {n & mask for n in nums}
        cand = best | (1 << bit)
        if any((cand ^ pre) in prefixes for pre in prefixes):
            best = cand
    return best
